class Solution {
public:
    string abbreviateProduct(int left, int right) {
        const long long MOD = 10000000000LL;
        const unsigned long long LIMIT = 10000000000ULL;

        int count2 = 0, count5 = 0;
        long long suffix = 1;
        unsigned long long exact = 1;
        long double logarithm = 0.0L;

        auto multiplyExact = [&](unsigned long long value) {
            if (exact >= LIMIT) return;
            __int128 product = static_cast<__int128>(exact) * value;
            exact = product >= LIMIT ? LIMIT
                                     : static_cast<unsigned long long>(product);
        };

        for (int value = left; value <= right; ++value) {
            logarithm += log10l(static_cast<long double>(value));

            int reduced = value;
            while (reduced % 2 == 0) {
                reduced /= 2;
                ++count2;
            }
            while (reduced % 5 == 0) {
                reduced /= 5;
                ++count5;
            }

            suffix = static_cast<long long>(
                static_cast<__int128>(suffix) * reduced % MOD
            );
            multiplyExact(reduced);
        }

        int zeros = min(count2, count5);
        count2 -= zeros;
        count5 -= zeros;

        while (count2--) {
            suffix = static_cast<long long>(
                static_cast<__int128>(suffix) * 2 % MOD
            );
            multiplyExact(2);
        }

        while (count5--) {
            suffix = static_cast<long long>(
                static_cast<__int128>(suffix) * 5 % MOD
            );
            multiplyExact(5);
        }

        if (exact < LIMIT) {
            return to_string(exact) + "e" + to_string(zeros);
        }

        long double reducedLog = logarithm - zeros;
        long double fractional = reducedLog - floorl(reducedLog);
        long long prefix = static_cast<long long>(
            floorl(powl(10.0L, fractional + 4.0L))
        );

        prefix = max(10000LL, min(99999LL, prefix));

        long long lastFive = suffix % 100000;
        string ending = to_string(lastFive);
        ending = string(5 - ending.size(), '0') + ending;

        return to_string(prefix) + "..." + ending + "e" + to_string(zeros);
    }
};
