        vector<string> result;
        int n = digits.size();

        if (n == 1 || digits[0] != '0') {
            result.push_back(digits);
        }

        for (int i = 1; i < n; ++i) {
            string integerPart = digits.substr(0, i);
            string fractionalPart = digits.substr(i);

            if (integerPart.size() > 1 && integerPart[0] == '0') continue;
            if (fractionalPart.back() == '0') continue;

            result.push_back(integerPart + "." + fractionalPart);
        }

        return result;
    }

