    vector<string> ambiguousCoordinates(string s) {
        string digits = s.substr(1, s.size() - 2);
        vector<string> answer;

        for (int i = 1; i < digits.size(); ++i) {
            vector<string> left = generate(digits.substr(0, i));
            vector<string> right = generate(digits.substr(i));

            for (const string& x : left) {
                for (const string& y : right) {
                    answer.push_back("(" + x + ", " + y + ")");
                }
            }
        }

        return answer;
    }
};
