public:
    int clumsy(int n) {
        int result = 0;
        int term = n;
        int operation = 0;

        for (int value = n - 1; value >= 1; --value) {
            if (operation == 0) {
                term *= value;
            } else if (operation == 1) {
                term /= value;
            } else if (operation == 2) {
                result += term;
                term = value;
            } else {
                result += term;
                term = -value;
            }
            operation = (operation + 1) % 4;
        }

        return result + term;
    }
};
