#include <bits/stdc++.h>
using namespace std;

class MKAverage {
private:
    int m, k;
    long long middleSum = 0;
    queue<int> window;
    multiset<int> low, middle, high;

    void moveLowToMiddle() {
        auto it = prev(low.end());
        int value = *it;
        low.erase(it);
        middle.insert(value);
        middleSum += value;
    }

    void moveHighToMiddle() {
        auto it = high.begin();
        int value = *it;
        high.erase(it);
        middle.insert(value);
        middleSum += value;
    }

    void moveMiddleToLow() {
        auto it = middle.begin();
        int value = *it;
        middle.erase(it);
        middleSum -= value;
        low.insert(value);
    }

    void moveMiddleToHigh() {
        auto it = prev(middle.end());
        int value = *it;
        middle.erase(it);
        middleSum -= value;
        high.insert(value);
    }

    void rebalance() {
        int n = window.size();
        int targetLow = min(k, n);
        int targetHigh = min(k, n - targetLow);

        while ((int)low.size() > targetLow) {
            moveLowToMiddle();
        }
        while ((int)high.size() > targetHigh) {
            moveHighToMiddle();
        }
        while ((int)low.size() < targetLow) {
            moveMiddleToLow();
        }
        while ((int)high.size() < targetHigh) {
            moveMiddleToHigh();
        }
    }

    void insertValue(int num) {
        if (!low.empty() && num <= *low.rbegin()) {
            low.insert(num);
        } else if (!high.empty() && num >= *high.begin()) {
            high.insert(num);
        } else {
            middle.insert(num);
            middleSum += num;
        }
    }

    void eraseValue(int num) {
        auto it = low.find(num);
        if (it != low.end()) {
            low.erase(it);
            return;
        }

        it = middle.find(num);
        if (it != middle.end()) {
            middleSum -= num;
            middle.erase(it);
            return;
        }

        it = high.find(num);
        if (it != high.end()) {
            high.erase(it);
        }
    }

public:
    MKAverage(int m, int k) {
        this->m = m;
        this->k = k;
    }

    void addElement(int num) {
        window.push(num);
        insertValue(num);

        if ((int)window.size() > m) {
            int removed = window.front();
            window.pop();
            eraseValue(removed);
        }

        rebalance();
    }

    int calculateMKAverage() {
        if ((int)window.size() < m) {
            return -1;
        }
        return static_cast<int>(middleSum / (m - 2 * k));
    }
};
```

