class Solution {
public:
    vector<int> numSmallerByFrequency(vector<string>& queries, vector<string>& words) {
        auto frequency = [](const string& s) {
            char smallest = s[0];
            int count = 0;

            for (char c : s) {
                if (c < smallest) {
                    smallest = c;
                    count = 1;
                } else if (c == smallest) {
                    ++count;
                }
            }
            return count;
        };

        vector<int> wordFrequencies;
        for (const string& word : words) {
            wordFrequencies.push_back(frequency(word));
        }
        sort(wordFrequencies.begin(), wordFrequencies.end());

        vector<int> answer;
        for (const string& query : queries) {
            int queryFrequency = frequency(query);
            auto it = upper_bound(wordFrequencies.begin(), wordFrequencies.end(),
                                  queryFrequency);
            answer.push_back(wordFrequencies.end() - it);
        }

        return answer;
    }
};
