class Solution {
public:
    bool canCross(vector<int>& stones) {
        int n = stones.size();
        if (stones[1] != 1) return false;
        if (n == 2) return true;

        unordered_map<int, int> index;
        for (int i = 0; i < n; ++i) {
            index[stones[i]] = i;
        }

        vector<vector<char>> reachable(n, vector<char>(n + 1, false));
        reachable[1][1] = true;

        for (int i = 1; i < n; ++i) {
            for (int jump = 1; jump < n; ++jump) {
                if (!reachable[i][jump]) continue;

                for (int nextJump = jump - 1; nextJump <= jump + 1; ++nextJump) {
                    if (nextJump <= 0 || nextJump > n) continue;

                    long long nextPosition =
                        static_cast<long long>(stones[i]) + nextJump;
                    if (nextPosition > INT_MAX) continue;

                    auto it = index.find(static_cast<int>(nextPosition));
                    if (it == index.end()) continue;

                    int nextIndex = it->second;
                    if (nextIndex == n - 1) return true;
                    reachable[nextIndex][nextJump] = true;
                }
            }
        }

        return false;
    }
};
