class Solution {
public:
    int maxScore(vector<int>& nums) {
        int m = nums.size();
        int fullMask = (1 << m) - 1;
        vector<int> dp(1 << m, -1);
        dp[0] = 0;

        auto gcd = [](int a, int b) {
            while (b != 0) {
                int remainder = a % b;
                a = b;
                b = remainder;
            }
            return a;
        };

        for (int mask = 0; mask <= fullMask; ++mask) {
            if (dp[mask] == -1) continue;

            int used = __builtin_popcount(mask);
            if (used == m) continue;

            int operation = used / 2 + 1;

            for (int i = 0; i < m; ++i) {
                if (mask & (1 << i)) continue;

                for (int j = i + 1; j < m; ++j) {
                    if (mask & (1 << j)) continue;

                    int nextMask = mask | (1 << i) | (1 << j);
                    int score = operation * gcd(nums[i], nums[j]);
                    dp[nextMask] = max(dp[nextMask], dp[mask] + score);
                }
            }
        }

        return dp[fullMask];
    }
};
