        int last[5] = {-1, -1, -1, -1, -1};
        int lastConsonant = -1;
        int answer = 0;

        for (int i = 0; i < word.size(); ++i) {
            int index = -1;

            if (word[i] == 'a') index = 0;
            else if (word[i] == 'e') index = 1;
            else if (word[i] == 'i') index = 2;
            else if (word[i] == 'o') index = 3;
            else if (word[i] == 'u') index = 4;

            if (index == -1) {
                lastConsonant = i;
            } else {
                last[index] = i;
                int earliest = last[0];
                for (int j = 1; j < 5; ++j) {
                    earliest = min(earliest, last[j]);
                }

                if (earliest > lastConsonant) {
                    answer += earliest - lastConsonant;
                }
            }
        }

        return answer;
    }
};
