    std::vector<int> pendingIncrement;

public:
    CustomStack(int maxSize) {
        capacity = maxSize;
    }

    void push(int x) {
        if (static_cast<int>(stack.size()) == capacity) {
            return;
        }

        stack.push_back(x);
        pendingIncrement.push_back(0);
    }

    int pop() {
        if (stack.empty()) {
            return -1;
        }

        int top = static_cast<int>(stack.size()) - 1;
        int result = stack[top] + pendingIncrement[top];

        if (top > 0) {
            pendingIncrement[top - 1] += pendingIncrement[top];
        }

        stack.pop_back();
        pendingIncrement.pop_back();
        return result;
    }

    void increment(int k, int val) {
        if (stack.empty()) {
            return;
        }

        int index = std::min(k, static_cast<int>(stack.size())) - 1;
        pendingIncrement[index] += val;
