class Solution {
public:
    int maximumANDSum(vector<int>& nums, int numSlots) {
        vector<int> power3(numSlots + 1, 1);
        for (int i = 1; i <= numSlots; ++i) {
            power3[i] = power3[i - 1] * 3;
        }

        int states = power3[numSlots];
        vector<int> dp(states, -1);
        dp[0] = 0;

        for (int num : nums) {
            vector<int> next(states, -1);

            for (int state = 0; state < states; ++state) {
                if (dp[state] == -1) continue;

                for (int slot = 0; slot < numSlots; ++slot) {
                    int occupancy = (state / power3[slot]) % 3;
                    if (occupancy < 2) {
                        int newState = state + power3[slot];
                        next[newState] = max(
                            next[newState],
                            dp[state] + (num & (slot + 1))
                        );
                    }
                }
            }

            dp.swap(next);
        }

        return *max_element(dp.begin(), dp.end());
    }
};
