class Solution {
public:
    int maxTotalFruits(vector<vector<int>>& fruits, int startPos, int k) {
        int left = 0;
        long long current = 0;
        long long answer = 0;

        auto stepsNeeded = [&](int leftPos, int rightPos) -> long long {
            if (rightPos <= startPos) {
                return startPos - leftPos;
            }
            if (leftPos >= startPos) {
                return rightPos - startPos;
            }

            long long leftDistance = startPos - leftPos;
            long long rightDistance = rightPos - startPos;
            return min(2 * leftDistance + rightDistance,
                       leftDistance + 2 * rightDistance);
