        for (int right = 0; right < static_cast<int>(fruits.size()); ++right) {
            current += fruits[right][1];

            while (left <= right &&
                   stepsNeeded(fruits[left][0], fruits[right][0]) > k) {
                current -= fruits[left][1];
                ++left;
            }

            answer = max(answer, current);
        }

        return static_cast<int>(answer);
    }
