class Solution {
public:
    vector<int> eventualSafeNodes(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<vector<int>> reverseGraph(n);
        vector<int> outDegree(n);

        for (int node = 0; node < n; ++node) {
            outDegree[node] = graph[node].size();
            for (int next : graph[node]) {
                reverseGraph[next].push_back(node);
            }
        }

        queue<int> q;
        for (int node = 0; node < n; ++node) {
            if (outDegree[node] == 0) {
                q.push(node);
            }
        }

        while (!q.empty()) {
            int safe = q.front();
            q.pop();

            for (int previous : reverseGraph[safe]) {
                if (--outDegree[previous] == 0) {
                    q.push(previous);
                }
            }
        }

        vector<int> result;
        for (int node = 0; node < n; ++node) {
            if (outDegree[node] == 0) {
                result.push_back(node);
            }
        }

        return result;
    }
};
