using namespace std;

class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size();
        int n = seats[0].size();
        int totalMasks = 1 << n;

        vector<int> available(m, 0);
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (seats[r][c] == '.') {
                    available[r] |= 1 << c;
                }
            }
        }

        vector<int> dp(totalMasks, -1), nextDp(totalMasks, -1);
        dp[0] = 0;

        for (int r = 0; r < m; ++r) {
            fill(nextDp.begin(), nextDp.end(), -1);

            for (int mask = 0; mask < totalMasks; ++mask) {
                if ((mask & ~available[r]) != 0) continue;
                if ((mask & (mask << 1)) != 0) continue;

                for (int prev = 0; prev < totalMasks; ++prev) {
                    if (dp[prev] == -1) continue;
                    if ((mask & (prev << 1)) != 0) continue;
                    if ((mask & (prev >> 1)) != 0) continue;

                    nextDp[mask] = max(
                        nextDp[mask],
                        dp[prev] + __builtin_popcount(mask)
                    );
                }
            }

            dp.swap(nextDp);
        }

        return *max_element(dp.begin(), dp.end());
    }
};
