class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        sort(flowers.begin(), flowers.end());

        int n = flowers.size();
        int incomplete = lower_bound(flowers.begin(), flowers.end(), target) - flowers.begin();

        vector<long long> prefix(incomplete + 1, 0);
        for (int i = 0; i < incomplete; ++i) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }

        long long answer = 0;
        int alreadyComplete = n - incomplete;

        for (int madeComplete = 0; madeComplete <= incomplete; ++madeComplete) {
            long long completionCost =
                1LL * madeComplete * target -
                (prefix[incomplete] - prefix[incomplete - madeComplete]);

            if (completionCost > newFlowers) break;

            int remaining = incomplete - madeComplete;
            long long beauty = 1LL * (alreadyComplete + madeComplete) * full;

            if (remaining > 0) {
                long long available = newFlowers - completionCost;
                int low = 0, high = target - 1, bestMinimum = 0;

                while (low <= high) {
                    int middle = low + (high - low) / 2;
                    int count = upper_bound(
                        flowers.begin(), flowers.begin() + remaining, middle
                    ) - flowers.begin();

                    long long cost = 1LL * middle * count - prefix[count];

                    if (cost <= available) {
                        bestMinimum = middle;
                        low = middle + 1;
                    } else {
                        high = middle - 1;
                    }
                }

                beauty += 1LL * bestMinimum * partial;
            }

            answer = max(answer, beauty);
        }

        return answer;
    }
};
