public:
    int minMalwareSpread(vector<vector<int>>& graph, vector<int>& initial) {
        int n = graph.size();
        int bestNode = n;
        int minInfected = n + 1;

        for (int removed : initial) {
            vector<bool> infected(n, false);
            vector<int> queue;

            for (int node : initial) {
                if (node != removed) {
                    infected[node] = true;
                    queue.push_back(node);
                }
            }

            for (int i = 0; i < static_cast<int>(queue.size()); ++i) {
                int node = queue[i];

                for (int next = 0; next < n; ++next) {
                    if (next != removed && graph[node][next] && !infected[next]) {
                        infected[next] = true;
                        queue.push_back(next);
                    }
                }
            }

            int infectedCount = queue.size();

            if (infectedCount < minInfected ||
                (infectedCount == minInfected && removed < bestNode)) {
                minInfected = infectedCount;
                bestNode = removed;
            }
        }

        return bestNode;
    }
