class Solution {
public:
    int minCost(int maxTime, vector<vector<int>>& edges, vector<int>& passingFees) {
        const int INF = 1e9;
        int n = passingFees.size();

        vector<vector<int>> dp(maxTime + 1, vector<int>(n, INF));
        dp[0][0] = passingFees[0];

        for (int time = 0; time <= maxTime; ++time) {
            for (const auto& edge : edges) {
                int u = edge[0];
                int v = edge[1];
                int travelTime = edge[2];
                int nextTime = time + travelTime;

                if (nextTime > maxTime) continue;

                if (dp[time][u] != INF) {
                    dp[nextTime][v] = min(
                        dp[nextTime][v],
                        dp[time][u] + passingFees[v]
                    );
                }

                if (dp[time][v] != INF) {
                    dp[nextTime][u] = min(
                        dp[nextTime][u],
                        dp[time][v] + passingFees[u]
                    );
                }
            }
        }

        int answer = INF;
        for (int time = 0; time <= maxTime; ++time) {
            answer = min(answer, dp[time][n - 1]);
        }

        return answer == INF ? -1 : answer;
    }
};
