            if (student == m) continue;

            for (int mentor = 0; mentor < m; ++mentor) {
                if (!(mask & (1 << mentor))) {
                    int nextMask = mask | (1 << mentor);
                    dp[nextMask] = max(dp[nextMask],
                                       dp[mask] + score[student][mentor]);
                }
            }
        }

        return dp[(1 << m) - 1];
    }
};
