class Solution {
public:
    int minDays(int n) {
        std::unordered_map<int, int> memo;

        auto dfs = [&](auto&& self, int oranges) -> int {
            if (oranges <= 1) return oranges;

            auto it = memo.find(oranges);
            if (it != memo.end()) return it->second;

            int byTwo = oranges % 2 + self(self, oranges / 2);
            int byThree = oranges % 3 + self(self, oranges / 3);

            return memo[oranges] = 1 + std::min(byTwo, byThree);
        };

        return dfs(dfs, n);
    }
};
