class Solution {
public:
    int numOfWays(vector<int>& nums) {
        const long long MOD = 1000000007LL;
        int n = nums.size();

        vector<vector<long long>> combinations(n + 1, vector<long long>(n + 1));
        for (int i = 0; i <= n; ++i) {
            combinations[i][0] = combinations[i][i] = 1;
            for (int j = 1; j < i; ++j) {
                combinations[i][j] =
                    (combinations[i - 1][j - 1] + combinations[i - 1][j]) % MOD;
            }
        }

        vector<int> left(n, -1), right(n, -1);

        for (int i = 1; i < n; ++i) {
            int current = 0;
            while (true) {
                if (nums[i] < nums[current]) {
                    if (left[current] == -1) {
                        left[current] = i;
                        break;
                    }
                    current = left[current];
                } else {
                    if (right[current] == -1) {
                        right[current] = i;
                        break;
                    }
                    current = right[current];
                }
            }
        }

        auto dfs = [&](auto&& self, int node) -> pair<int, long long> {
            if (node == -1) return {0, 1};

            auto [leftSize, leftWays] = self(self, left[node]);
            auto [rightSize, rightWays] = self(self, right[node]);

            long long ways = combinations[leftSize + rightSize][leftSize];
            ways = ways * leftWays % MOD;
            ways = ways * rightWays % MOD;

            return {leftSize + rightSize + 1, ways};
        };

        long long totalWays = dfs(dfs, 0).second;
        return static_cast<int>((totalWays - 1 + MOD) % MOD);
    }
};
