class Solution {
public:
    int maxSizeSlices(vector<int>& slices) {
        const int total = slices.size();
        const int picks = total / 3;
        const int NEG = -1000000000;

        auto solve = [&](int left, int right) {
            int length = right - left + 1;
            vector<vector<int>> dp(length + 1,
                                   vector<int>(picks + 1, NEG));
            dp[0][0] = 0;

            for (int i = 1; i <= length; ++i) {
                dp[i][0] = 0;
                for (int j = 1; j <= picks; ++j) {
                    dp[i][j] = dp[i - 1][j];

                    int previous = (i >= 2) ? dp[i - 2][j - 1]
                                            : (j == 1 ? 0 : NEG);
                    if (previous != NEG) {
                        dp[i][j] = max(
                            dp[i][j],
                            previous + slices[left + i - 1]
                        );
                    }
                }
            }

            return dp[length][picks];
        };

        return max(solve(0, total - 2), solve(1, total - 1));
    }
};
