class Solution {
public:
    vector<bool> friendRequests(int n, vector<vector<int>>& restrictions, vector<vector<int>>& requests) {
        vector<int> parent(n), size(n, 1);
        for (int i = 0; i < n; ++i) {
            parent[i] = i;
        }

        auto find = [&](auto&& self, int x) -> int {
            if (parent[x] == x) {
                return x;
            }
            return parent[x] = self(self, parent[x]);
        };

        vector<bool> result;
        result.reserve(requests.size());

        for (const auto& request : requests) {
            int rootU = find(find, request[0]);
            int rootV = find(find, request[1]);

            if (rootU == rootV) {
                result.push_back(true);
                continue;
            }

            bool valid = true;

            for (const auto& restriction : restrictions) {
                int rootX = find(find, restriction[0]);
                int rootY = find(find, restriction[1]);

                if ((rootX == rootU && rootY == rootV) ||
                    (rootX == rootV && rootY == rootU)) {
                    valid = false;
                    break;
                }
            }

            result.push_back(valid);

            if (valid) {
                if (size[rootU] < size[rootV]) {
                    swap(rootU, rootV);
                }
                parent[rootV] = rootU;
                size[rootU] += size[rootV];
