class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        int removeLeft = 0, removeRight = 0;

        for (char c : s) {
            if (c == '(') {
                ++removeLeft;
            } else if (c == ')') {
                if (removeLeft > 0) {
                    --removeLeft;
                } else {
                    ++removeRight;
                }
            }
        }

        unordered_set<string> valid;
        string current;

        function<void(int, int, int, int)> dfs =
            [&](int index, int leftRem, int rightRem, int balance) {
                if (leftRem + rightRem > static_cast<int>(s.size()) - index) {
                    return;
                }

                if (index == static_cast<int>(s.size())) {
                    if (leftRem == 0 && rightRem == 0 && balance == 0) {
                        valid.insert(current);
                    }
                    return;
                }

                char c = s[index];

                if (c == '(') {
                    if (leftRem > 0) {
                        dfs(index + 1, leftRem - 1, rightRem, balance);
                    }

                    current.push_back(c);
                    dfs(index + 1, leftRem, rightRem, balance + 1);
                    current.pop_back();
                } else if (c == ')') {
                    if (rightRem > 0) {
                        dfs(index + 1, leftRem, rightRem - 1, balance);
                    }

                    if (balance > 0) {
                        current.push_back(c);
                        dfs(index + 1, leftRem, rightRem, balance - 1);
                        current.pop_back();
                    }
                } else {
                    current.push_back(c);
                    dfs(index + 1, leftRem, rightRem, balance);
                    current.pop_back();
                }
            };

        dfs(0, removeLeft, removeRight, 0);
        return vector<string>(valid.begin(), valid.end());
    }
};
