class Solution {
public:
    int numTriplets(vector<int>& nums1, vector<int>& nums2) {
        vector<int> a = nums1;
        vector<int> b = nums2;
        sort(a.begin(), a.end());
        sort(b.begin(), b.end());

        auto countTriplets = [](const vector<int>& squares,
                                const vector<int>& products) -> long long {
            long long result = 0;

            for (int x : squares) {
                long long target = 1LL * x * x;
                int left = 0;
                int right = static_cast<int>(products.size()) - 1;

                while (left < right) {
                    long long product = 1LL * products[left] * products[right];

                    if (product < target) {
                        ++left;
                    } else if (product > target) {
                        --right;
                    } else if (products[left] == products[right]) {
                        long long count = right - left + 1;
                        result += count * (count - 1) / 2;
                        break;
                    } else {
                        long long leftCount = 1;
                        long long rightCount = 1;

                        while (left + leftCount < right &&
                               products[left + leftCount] == products[left]) {
                            ++leftCount;
                        }

                        while (right - rightCount > left &&
                               products[right - rightCount] == products[right]) {
                            ++rightCount;
                        }

                        result += leftCount * rightCount;
                        left += static_cast<int>(leftCount);
                        right -= static_cast<int>(rightCount);
                    }
                }
            }

            return result;
        };

        return static_cast<int>(countTriplets(a, b) + countTriplets(b, a));
    }
};
