class Solution {
public:
    vector<double> medianSlidingWindow(vector<int>& nums, int k) {
        multiset<int> lower, upper;

        auto rebalance = [&]() {
            while (lower.size() > upper.size() + 1) {
                auto it = prev(lower.end());
                upper.insert(*it);
                lower.erase(it);
            }
            while (lower.size() < upper.size()) {
                auto it = upper.begin();
                lower.insert(*it);
                upper.erase(it);
            }
        };

        auto insertValue = [&](int value) {
            if (lower.empty() || value <= *lower.rbegin()) {
                lower.insert(value);
            } else {
                upper.insert(value);
            }
            rebalance();
        };

        auto eraseValue = [&](int value) {
            auto it = lower.find(value);
            if (it != lower.end()) {
                lower.erase(it);
            } else {
                upper.erase(upper.find(value));
            }
            rebalance();
        };

        auto getMedian = [&]() -> double {
            if (k % 2 == 1) {
                return static_cast<double>(*lower.rbegin());
            }
            long long left = *lower.rbegin();
            long long right = *upper.begin();
            return (left + right) / 2.0;
        };

        for (int i = 0; i < k; ++i) {
            insertValue(nums[i]);
        }

        vector<double> medians;
        medians.reserve(nums.size() - k + 1);
        medians.push_back(getMedian());

        for (int i = k; i < static_cast<int>(nums.size()); ++i) {
            eraseValue(nums[i - k]);
            insertValue(nums[i]);
            medians.push_back(getMedian());
        }

        return medians;
    }
};
