class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        long long low = 0, high = 0;

        for (int num : nums) {
            low = max(low, static_cast<long long>(num));
            high += num;
        }

        while (low < high) {
            long long mid = low + (high - low) / 2;
            int subarrays = 1;
            long long currentSum = 0;

            for (int num : nums) {
                if (currentSum + num > mid) {
                    ++subarrays;
                    currentSum = num;
                } else {
                    currentSum += num;
                }
            }

            if (subarrays <= k) {
                high = mid;
