class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int m = target.size();
        int fullMask = (1 << m) - 1;
        const int INF = 1e9;

        vector<int> dp(1 << m, INF);
        dp[0] = 0;

        for (int mask = 0; mask <= fullMask; ++mask) {
            if (dp[mask] == INF) continue;

            for (const string& sticker : stickers) {
                int nextMask = mask;

                for (char c : sticker) {
                    for (int i = 0; i < m; ++i) {
                        if (!(nextMask & (1 << i)) && target[i] == c) {
                            nextMask |= 1 << i;
                            break;
                        }
                    }
                }

                dp[nextMask] = min(dp[nextMask], dp[mask] + 1);
            }
        }

        return dp[fullMask] == INF ? -1 : dp[fullMask];
    }
};
