            for (int col = 0; col < n; ++col) {
                if (grid[row][col] == '/') {
                    expanded[row * 3][col * 3 + 2] = 1;
                    expanded[row * 3 + 1][col * 3 + 1] = 1;
                    expanded[row * 3 + 2][col * 3] = 1;
                } else if (grid[row][col] == '\\') {
