        int directions[5] = {-1, 0, 1, 0, -1};

        for (int row = 0; row < size; ++row) {
            for (int col = 0; col < size; ++col) {
                if (expanded[row][col] != 0) continue;

                ++regions;
                vector<pair<int, int>> stack = {{row, col}};
                expanded[row][col] = 1;

                while (!stack.empty()) {
