class Solution {
    int earliest[29][29][29];
    int latest[29][29][29];

    pair<int, int> solve(int n, int firstPlayer, int secondPlayer) {
        int reflectedFirst = n + 1 - secondPlayer;
        int reflectedSecond = n + 1 - firstPlayer;

        if (reflectedFirst < firstPlayer) {
            firstPlayer = reflectedFirst;
            secondPlayer = reflectedSecond;
        }

        if (firstPlayer + secondPlayer == n + 1) {
            return {1, 1};
        }

        if (earliest[n][firstPlayer][secondPlayer] != 0) {
            return {
                earliest[n][firstPlayer][secondPlayer],
                latest[n][firstPlayer][secondPlayer]
            };
        }

        vector<vector<int>> options;

        for (int left = 1; left <= n / 2; ++left) {
            int right = n + 1 - left;

            if (left == firstPlayer || right == firstPlayer) {
                options.push_back({firstPlayer});
            } else if (left == secondPlayer || right == secondPlayer) {
                options.push_back({secondPlayer});
            } else {
                options.push_back({left, right});
            }
        }

        if (n % 2 == 1) {
            options.push_back({n / 2 + 1});
        }

        unordered_set<int> nextStates;

        function<void(int, int, int)> generate = [&](int index, int beforeFirst, int beforeSecond) {
            if (index == static_cast<int>(options.size())) {
                int nextFirst = beforeFirst + 1;
                int nextSecond = beforeSecond + 1;
                nextStates.insert(nextFirst * 32 + nextSecond);
                return;
            }

            for (int winner : options[index]) {
                generate(
                    index + 1,
                    beforeFirst + (winner < firstPlayer),
                    beforeSecond + (winner < secondPlayer)
                );
            }
        };

        generate(0, 0, 0);

        int nextN = (n + 1) / 2;
        int minRound = INT_MAX;
        int maxRound = 0;

        for (int state : nextStates) {
            int nextFirst = state / 32;
            int nextSecond = state % 32;

            auto result = solve(nextN, nextFirst, nextSecond);
            minRound = min(minRound, result.first + 1);
            maxRound = max(maxRound, result.second + 1);
        }

        earliest[n][firstPlayer][secondPlayer] = minRound;
        latest[n][firstPlayer][secondPlayer] = maxRound;

        return {minRound, maxRound};
    }

public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memset(earliest, 0, sizeof(earliest));
        memset(latest, 0, sizeof(latest));

        auto result = solve(n, firstPlayer, secondPlayer);
        return {result.first, result.second};
    }
};
