class Solution {
public:
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        vector<vector<int>> graph(n);

        for (const auto& edge : edges) {
            graph[edge[0]].push_back(edge[1]);
            graph[edge[1]].push_back(edge[0]);
        }

        auto gcd = [](int a, int b) {
            while (b != 0) {
                int remainder = a % b;
                a = b;
                b = remainder;
            }
            return a;
        };

        vector<vector<int>> coprimeValues(51);
        for (int value = 1; value <= 50; ++value) {
            for (int other = 1; other <= 50; ++other) {
                if (gcd(value, other) == 1) {
                    coprimeValues[value].push_back(other);
                }
            }
        }

        vector<vector<pair<int, int>>> ancestors(51);
        vector<int> answer(n, -1);

        struct Event {
            int node;
            int parent;
            int depth;
            bool exiting;
        };

        vector<Event> events;
        events.reserve(2 * n);
        events.push_back({0, -1, 0, false});

        while (!events.empty()) {
            Event event = events.back();
            events.pop_back();

            int node = event.node;
            int value = nums[node];

            if (event.exiting) {
                ancestors[value].pop_back();
                continue;
            }

            int bestDepth = -1;
            for (int coprimeValue : coprimeValues[value]) {
                if (!ancestors[coprimeValue].empty()) {
