                    if (depth > bestDepth) {
                        bestDepth = depth;
                        answer[node] = ancestorNode;
                    }
                }
            }

            ancestors[value].push_back({event.depth, node});
            events.push_back({node, event.parent, event.depth, true});

            for (int next : graph[node]) {
                if (next != event.parent) {
                    events.push_back({next, node, event.depth + 1, false});
                }
            }
        }

        return answer;
    }
