        vector<int> indegree(n, 0);

        for (int i = 0; i < n; ++i) {
            for (int child : {leftChild[i], rightChild[i]}) {
                if (child != -1 && ++indegree[child] > 1) {
                    return false;
                }
            }
        }

        int root = -1;
        for (int i = 0; i < n; ++i) {
            if (indegree[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }

        if (root == -1) return false;

        vector<bool> visited(n, false);
        queue<int> nodes;
        nodes.push(root);
        int count = 0;

        while (!nodes.empty()) {
            int node = nodes.front();
            nodes.pop();

            if (visited[node]) return false;
            visited[node] = true;
            ++count;

            if (leftChild[node] != -1) {
                nodes.push(leftChild[node]);
            }
            if (rightChild[node] != -1) {
                nodes.push(rightChild[node]);
            }
        }

        return count == n;
    }
};
